// Verification script for check-in label template changes.
// Renders the HTML generated by buildLabelHtml() in headless Chromium and
// saves screenshots for each scenario so we can eyeball the layout without
// needing a real Zebra printer.
//
// Scenarios:
//   1. Single service (label is both first + last → has CHECK-IN header AND QR)
//   2. First of 3 services (header + service, no QR, "continued 1/3")
//   3. Middle of 3 services (customer name + page tag, no QR, "continued 2/3")
//   4. Last of 3 services (customer name + page tag + service + TOTAL + staff + notes + QR)

import { chromium } from 'playwright';
import { writeFileSync, mkdirSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { createRequire } from 'module';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..', '..');
const OUT = join(ROOT, 'tests', 'e2e', 'screenshots');
if (!existsSync(OUT)) mkdirSync(OUT, { recursive: true });

const require = createRequire(import.meta.url);
const { buildLabelHtml } = require(join(ROOT, 'dist', 'main', 'hardware', 'pdf', 'pdf-printer.js'));

const WIDTH_MM = 50;
const HEIGHT_MM = 30;
// CSS 1mm = 96/25.4 ≈ 3.78px — the label body CSS uses mm units, so the
// actual rendered box is this size. We use deviceScaleFactor for a sharper preview.
const CSS_PX_PER_MM = 96 / 25.4;

const baseData = {
  bookingNumber: '001/0410',
  customerName: 'Anna Nguyen',
  customerPhone: '+48123456789',
  customerNotes: 'Allergic to acetone, prefers gel polish',
  staffName: 'Maria',
  checkinTime: new Date('2026-04-10T14:30:00').toISOString(),
  isWalkIn: false,
};

const services = [
  { name: 'Manicure Classic', price: 8000 },
  { name: 'Pedicure Spa', price: 12000 },
  { name: 'Gel polish', price: 6000 },
];

// Mimics a real printed label that overflowed: long Polish service name + long staff name.
const longStaffData = {
  bookingNumber: '003/1004',
  customerName: 'GY',
  customerPhone: '+48123456789',
  customerNotes: '',
  staffName: 'Maria Wiśniewska',
  checkinTime: new Date('2026-04-10T13:17:00').toISOString(),
  isWalkIn: false,
};
const longServices = [
  { name: 'Aceton kosmetyczny 1000ml', price: 1900 },
  { name: 'Frezarka do paznokci 35000rpm', price: 29900 },
  { name: 'Krem pod oczy 15ml', price: 7200 },
  { name: 'Nożyczki fryzjerskie 6"', price: 8900 },
];

const scenarios = [
  {
    name: 'single-service',
    opts: {
      printerName: 'mock',
      labelWidthMm: WIDTH_MM,
      labelHeightMm: HEIGHT_MM,
      salonName: 'Zira Salon',
      data: { ...baseData, services: [services[0]] },
    },
  },
  {
    name: 'multi-1of3-first',
    opts: {
      printerName: 'mock',
      labelWidthMm: WIDTH_MM,
      labelHeightMm: HEIGHT_MM,
      salonName: 'Zira Salon',
      data: { ...baseData, services: [services[0]] },
      pageInfo: { page: 1, total: 3 },
      grandTotal: 26000,
    },
  },
  {
    name: 'multi-2of3-middle',
    opts: {
      printerName: 'mock',
      labelWidthMm: WIDTH_MM,
      labelHeightMm: HEIGHT_MM,
      salonName: 'Zira Salon',
      data: { ...baseData, services: [services[1]] },
      pageInfo: { page: 2, total: 3 },
      grandTotal: 26000,
    },
  },
  {
    name: 'multi-3of3-last',
    opts: {
      printerName: 'mock',
      labelWidthMm: WIDTH_MM,
      labelHeightMm: HEIGHT_MM,
      salonName: 'Zira Salon',
      data: { ...baseData, services: [services[2]] },
      pageInfo: { page: 3, total: 3 },
      grandTotal: 26000,
    },
  },
  {
    name: 'longname-1of4-first',
    opts: {
      printerName: 'mock',
      labelWidthMm: WIDTH_MM,
      labelHeightMm: HEIGHT_MM,
      salonName: 'Zira AI',
      data: { ...longStaffData, services: [longServices[0]] },
      pageInfo: { page: 1, total: 4 },
      grandTotal: 47900,
    },
  },
  {
    name: 'longname-2of4-middle',
    opts: {
      printerName: 'mock',
      labelWidthMm: WIDTH_MM,
      labelHeightMm: HEIGHT_MM,
      salonName: 'Zira AI',
      data: { ...longStaffData, services: [longServices[1]] },
      pageInfo: { page: 2, total: 4 },
      grandTotal: 47900,
    },
  },
  {
    name: 'longname-4of4-last',
    opts: {
      printerName: 'mock',
      labelWidthMm: WIDTH_MM,
      labelHeightMm: HEIGHT_MM,
      salonName: 'Zira AI',
      data: { ...longStaffData, services: [longServices[3]] },
      pageInfo: { page: 4, total: 4 },
      grandTotal: 47900,
    },
  },
];

const browser = await chromium.launch();
const context = await browser.newContext({
  viewport: {
    width: Math.ceil(WIDTH_MM * CSS_PX_PER_MM),
    height: Math.ceil(HEIGHT_MM * CSS_PX_PER_MM),
  },
  deviceScaleFactor: 5,
});

for (const scn of scenarios) {
  const html = await buildLabelHtml(scn.opts);
  const htmlPath = join(OUT, `checkin-label-${scn.name}.html`);
  writeFileSync(htmlPath, html, 'utf-8');

  const page = await context.newPage();
  await page.setContent(html, { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(200);
  const pngPath = join(OUT, `checkin-label-${scn.name}.png`);
  await page.screenshot({ path: pngPath, fullPage: false });
  await page.close();
  console.log(`[verify] ${scn.name} → ${pngPath}`);
}

await browser.close();
console.log('[verify] Done — 4 scenarios rendered.');
